+  PEXCEPTION_RECORD exception_record = exceptionInfo->ExceptionRecord;
+  tty->print_raw_cr(message);
+  VMError::report_and_die(thread, exception_record->ExceptionCode, pc,
+                          exception_record, exceptionInfo->ContextRecord);
+}
